from pathlib import Path
class Node:
 def __init__(self,data,start):
  self.data=data; self.start=start; p=start; t=data[p]; p+=1
  self.cls=t&192; self.cons=bool(t&32); self.tag=t&31
  if self.tag==31:
   self.tag=0
   while True:
    b=data[p]; p+=1; self.tag=self.tag*128+(b&127)
    if b<128: break
  self.tagend=p
  b=data[p]; p+=1; self.indef=b==128
  if b>128:
   size=b&127; n=int.from_bytes(data[p:p+size],'big'); p+=size
  else: n=b
  self.header=data[self.tagend:p]; self.content=p; self.children=[]
  if self.indef:
   while data[p:p+2]!=b'\0\0':
    c=Node(data,p); self.children.append(c); p=c.end
   self.stop=p; self.end=p+2
  else:
   self.stop=p+n; self.end=self.stop
   if self.cons:
    while p<self.stop:
     c=Node(data,p); self.children.append(c); p=c.end
  self.value=data[self.content:self.stop]
  self.raw=data[start:self.end]
 def walk(self,path=''):
  yield path,self
  for i,c in enumerate(self.children): yield from c.walk(path+'/'+str(i))
def enc_len(n):
 if n<128: return bytes([n])
 b=n.to_bytes((n.bit_length()+7)//8,'big'); return bytes([128+len(b)])+b
def anomalies(root):
 for p,n in root.walk():
  a=[]
  if n.indef: a.append('indef')
  elif n.header!=enc_len(len(n.value)): a.append('length='+n.header.hex())
  if n.cls==0 and n.tag in (3,4) and n.cons: a.append('constructed string')
  if n.cls==0 and n.tag==2 and len(n.value)>1 and ((n.value[0]==0 and n.value[1]<128) or (n.value[0]==255 and n.value[1]>=128)): a.append('padded int '+n.value.hex())
  if n.cls==0 and n.tag==1: a.append('bool '+n.value.hex())
  if n.cls==0 and n.tag==17 and any(x.raw>=y.raw for x,y in zip(n.children,n.children[1:])): a.append('set order')
  if n.cls==0 and n.tag==4 and n.value[:1]==b'\x30':
   try:
    inner=Node(n.value,0)
    if inner.end==len(n.value):
     for ip,inn,ia in anomalies(inner): a.append('inner '+ip+' @'+str(n.content+inn.start)+' '+ia)
   except Exception: pass
  if a: yield p,n,', '.join(a)
if __name__=='__main__':
 for f in sorted(Path('/app/corpus').glob('*.der')):
  print('\n'+f.name)
  for p,n,a in anomalies(Node(f.read_bytes(),0)): print(n.start,p,a)
