                for b in value:
                    subidentifier = (subidentifier << 7) | (b & 127)
                    if b < 128:
                        groups = [subidentifier & 127]
                        subidentifier >>= 7
                        while subidentifier:
                            groups.append(128 | (subidentifier & 127))
